<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\{Pet,PetImage};
use App\Services\ImageOptimizer;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
class PetController extends Controller { public function index(){return view('admin.pets.index',['pets'=>Pet::with('primaryImage')->latest()->paginate(20)]);} public function create(){return view('admin.pets.form',['pet'=>new Pet]);} private function validated(Request $r,?Pet $pet=null): array{return $r->validate(['name'=>'required|string|max:100','slug'=>['nullable','string','max:140',Rule::unique('pets')->ignore($pet?->id)],'animal_type'=>'required|in:dog,cat','breed'=>'nullable|string|max:100','date_of_birth'=>'nullable|date|before_or_equal:today','age_group'=>'required|in:baby,young,adult,senior','gender'=>'required|in:male,female,unknown','status'=>'required|in:available,adopted,fostered','description'=>'required|string|max:5000','health_info'=>'nullable|string|max:3000','is_spayed_neutered'=>'nullable|boolean','is_vaccinated'=>'nullable|boolean','is_published'=>'nullable|boolean','images.*'=>'image|mimes:jpg,jpeg,png,webp|max:5120']);} public function store(Request $r,ImageOptimizer $images){$data=$this->validated($r);$data['slug']=$data['slug']?:Str::slug($data['name']).'-'.Str::lower(Str::random(5));foreach(['is_spayed_neutered','is_vaccinated','is_published'] as $b)$data[$b]=$r->boolean($b);DB::transaction(function()use($r,$data,$images){$pet=Pet::create($data);foreach($r->file('images',[]) as $i=>$file)$pet->images()->create(['path'=>$images->store($file,'pets'),'sort_order'=>$i,'is_primary'=>$i===0]);});return redirect()->route('admin.pets.index')->with('success','တိရစ္ဆာန်မှတ်တမ်း ထည့်ပြီးပါပြီ။');} public function edit(Pet $pet){$pet->load('images');return view('admin.pets.form',compact('pet'));} public function update(Request $r,Pet $pet,ImageOptimizer $images){$data=$this->validated($r,$pet);$data['slug']=$data['slug']?:$pet->slug;foreach(['is_spayed_neutered','is_vaccinated','is_published'] as $b)$data[$b]=$r->boolean($b);DB::transaction(function()use($r,$data,$pet,$images){$pet->update($data);$start=(int)$pet->images()->max('sort_order')+1;foreach($r->file('images',[]) as $i=>$file)$pet->images()->create(['path'=>$images->store($file,'pets'),'sort_order'=>$start+$i,'is_primary'=>$pet->images()->count()===0]);});return redirect()->route('admin.pets.index')->with('success','ပြင်ဆင်ပြီးပါပြီ။');} public function destroy(Pet $pet,ImageOptimizer $images){foreach($pet->images as $image)$images->delete($image->path);$pet->forceDelete();return back()->with('success','ဖျက်ပြီးပါပြီ။');} public function destroyImage(PetImage $image,ImageOptimizer $images){$pet=$image->pet;$was=$image->is_primary;$images->delete($image->path);$image->delete();if($was&&$next=$pet->images()->first())$next->update(['is_primary'=>true]);return back()->with('success','ဓာတ်ပုံဖျက်ပြီးပါပြီ။');} }
